public class TimeSelectionControlProbe extends GridFinalProbe {
 final Object book;Object system;List<?> originalStaves;final IdentityHashMap<Object,String> labels=new IdentityHashMap<>();int generatedBase,observedMaxHalvesDx;
 public TimeSelectionControlProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static Class<?> cls(String n)throws Exception{return Class.forName(n);}
 static void set(Object o,String n,Object v)throws Exception{KeyBuilderProcessProbe.put(o,n,v);}
 static Map<String,Object> m(Object... a){Map<String,Object> x=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)x.put((String)a[i],a[i+1]);return x;}
 static String json(Object v){if(v==null)return "null";if(v instanceof String s)return KeyBuilderProcessProbe.q(s);if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof Map<?,?> map){List<String>x=new ArrayList<>();for(var e:map.entrySet())x.add(json(e.getKey())+":"+json(e.getValue()));return "{"+String.join(",",x)+"}";}if(v instanceof Iterable<?> l){List<String>x=new ArrayList<>();for(Object a:l)x.add(json(a));return "["+String.join(",",x)+"]";}if(v.getClass().isArray()){List<String>x=new ArrayList<>();for(int i=0;i<Array.getLength(v);i++)x.add(json(Array.get(v,i)));return "["+String.join(",",x)+"]";}throw new IllegalArgumentException(v.getClass().toString());}
 String label(Object o){if(o==null)return null;if(!labels.containsKey(o)){try{labels.put(o,"generated_"+((Integer)call(o,"getId")-generatedBase));}catch(Exception e){throw new RuntimeException(e);}}return labels.get(o);}
 Map<String,Object> inter(Object o)throws Exception{
  if(o==null)return null;boolean emptyPair=o.getClass().getSimpleName().equals("TimePairInter")&&((List<?>)call(o,"getMembers")).isEmpty();Rectangle r=emptyPair?null:(Rectangle)call(o,"getBounds");Map<String,Object>x=m("label",label(o),"kind",o.getClass().getSimpleName(),"shape",call(o,"getShape")==null?null:call(o,"getShape").toString(),"grade",call(o,"getGrade"),"contextual_grade",call(o,"getContextualGrade"),"removed",call(o,"isRemoved"),"bounds",r==null?null:new int[]{r.x,r.y,r.width,r.height});
  if(o.getClass().getSimpleName().equals("TimeNumberInter"))x.put("value",call(o,"getValue"));
  if(cls("org.audiveris.omr.sig.inter.AbstractTimeInter").isInstance(o))x.put("time_value",call(o,"getValue")==null?null:call(o,"getValue").toString());
  if(o.getClass().getSimpleName().equals("TimePairInter")){List<String> members=new ArrayList<>();for(Object a:(List<?>)call(o,"getMembers"))members.add(label(a));x.put("members",members);}return x;
 }
 Map<String,Object> edge(Object sig,Object e)throws Exception{Map<String,Object>x=m("kind",e.getClass().getSimpleName(),"source",label(call(sig,"getEdgeSource",e)),"target",label(call(sig,"getEdgeTarget",e)));if(e.getClass().getSimpleName().equals("Exclusion"))x.put("cause",get(e,"cause").toString());return x;}
 Map<String,Object> snapshot(Object sig,Map<Object,Object> builders)throws Exception{
  List<Object> verts=new ArrayList<>(),rels=new ArrayList<>(),staffs=new ArrayList<>();for(Object o:(Collection<?>)call(sig,"vertexSet"))verts.add(inter(o));for(Object e:(Collection<?>)call(sig,"edgeSet"))rels.add(edge(sig,e));
  for(var e:builders.entrySet()){Object b=e.getValue();Map<String,Object>x=m("staff_index",originalStaves.indexOf(e.getKey()),"selected",inter(get(b,"timeInter")),"time_stop",call(e.getKey(),"getTimeStop"));for(String n:new String[]{"wholes","nums","dens"}){List<String> a=new ArrayList<>();for(Object i:(List<?>)get(b,n))a.add(label(i));x.put(n,a);}staffs.add(x);}return m("inters",verts,"relations",rels,"staffs",staffs);
 }
 @SuppressWarnings("unchecked") Map<String,Object> runPass(List<Map<String,Object>> inputs,int count,boolean selection)throws Exception{
  labels.clear();generatedBase=0;List<?> staves=originalStaves.subList(0,count);set(system,"staves",new ArrayList<>(staves));Object sig=cls("org.audiveris.omr.sig.SIGraph").getConstructor(cls("org.audiveris.omr.sheet.SystemInfo")).newInstance(system);set(system,"sig",sig);
  Object column=cls("org.audiveris.omr.sheet.time.HeaderTimeColumn").getConstructor(cls("org.audiveris.omr.sheet.SystemInfo")).newInstance(system);Map<Object,Object> builders=(Map<Object,Object>)get(column,"builders");List<Object> events=new ArrayList<>();Class<?> listener=cls("org.jgrapht.event.GraphListener");
  sig.getClass().getMethod("addGraphListener",listener).invoke(sig,cls("org.audiveris.omr.sig.SigListener").getConstructor(cls("org.audiveris.omr.sig.SIGraph")).newInstance(sig));
  Object proxy=Proxy.newProxyInstance(listener.getClassLoader(),new Class<?>[]{listener},(p,method,args)->{if(method.getName().equals("hashCode"))return System.identityHashCode(p);if(method.getName().equals("equals"))return p==args[0];if(method.getName().equals("toString"))return "TimeControlListener";if(method.getName().startsWith("edge")){Object ev=args[0],e=call(ev,"getEdge");Map<String,Object>x=m("event",method.getName(),"kind",e.getClass().getSimpleName(),"source",label(call(ev,"getEdgeSource")),"target",label(call(ev,"getEdgeTarget")));if(e.getClass().getSimpleName().equals("Exclusion"))x.put("cause",get(e,"cause").toString());events.add(x);}return null;});if(!Boolean.getBoolean("native.probe.plainTimeControl"))sig.getClass().getMethod("addGraphListener",listener).invoke(sig,proxy);
  for(Object staff:staves){set(staff,"barlines",new ArrayList<>());Object header=cls("org.audiveris.omr.sheet.header.StaffHeader").getConstructor(int.class).newInstance(102);set(header,"stop",158);set(staff,"header",header);Object b=cls("org.audiveris.omr.sheet.time.HeaderTimeBuilder").getConstructor(cls("org.audiveris.omr.sheet.Staff"),cls("org.audiveris.omr.sheet.time.TimeColumn"),int.class).newInstance(staff,column,158);builders.put(staff,b);observedMaxHalvesDx=(Integer)get(get(b,"params"),"maxHalvesDx");}
  List<Object> inserted=new ArrayList<>();for(Map<String,Object> in:inputs){Object staff=staves.get((Integer)in.get("staff_index")),shape=cls("org.audiveris.omr.glyph.Shape").getField((String)in.get("shape")).get(null),value;String kind=(String)in.get("kind");double grade=(Double)in.get("grade");
   if(kind.equals("WHOLE"))value=cls("org.audiveris.omr.sig.inter.TimeWholeInter").getConstructor(cls("org.audiveris.omr.glyph.Glyph"),cls("org.audiveris.omr.glyph.Shape"),Double.class).newInstance(null,shape,grade);
   else if(kind.equals("NEIGHBOR"))value=cls("org.audiveris.omr.sig.inter.KeyAlterInter").getConstructor(cls("org.audiveris.omr.glyph.Glyph"),cls("org.audiveris.omr.glyph.Shape"),Double.class,cls("org.audiveris.omr.sheet.Staff"),Double.class,Double.class).newInstance(null,shape,grade,null,0.0,0.0);
   else value=cls("org.audiveris.omr.sig.inter.TimeNumberInter").getConstructor(cls("org.audiveris.omr.glyph.Glyph"),cls("org.audiveris.omr.glyph.Shape"),Double.class,cls("org.audiveris.omr.util.VerticalSide")).newInstance(null,shape,grade,cls("org.audiveris.omr.util.VerticalSide").getField(kind.equals("NUM")?"TOP":"BOTTOM").get(null));
   labels.put(value,(String)in.get("label"));call(value,"setStaff",staff);int[] r=(int[])in.get("bounds");call(value,"setBounds",new Rectangle(r[0],r[1],r[2],r[3]));call(sig,"addVertex",value);inserted.add(value);generatedBase=Math.max(generatedBase,(Integer)call(value,"getId"));if(!kind.equals("NEIGHBOR"))((List<Object>)get(builders.get(staff),kind.equals("WHOLE")?"wholes":kind.equals("NUM")?"nums":"dens")).add(value);
  }
  List<Boolean> filters=new ArrayList<>();for(Object b:builders.values())filters.add((Boolean)call(b,"filterCandidates"));Map<String,Object> afterFilter=snapshot(sig,builders);List<Object> inputStates=new ArrayList<>();for(Object v:inserted)inputStates.add(inter(v));Map<String,Object> result=m("filter_results",filters,"after_filter",afterFilter,"input_inter_states_after_filter",inputStates);
  if(selection){boolean ok=(Boolean)call(column,"checkConsistency");result.put("returned_bool",ok);result.put("time_value",get(column,"timeValue")==null?null:get(column,"timeValue").toString());}
  else{Map<?,?> vectors=(Map<?,?>)call(column,"getValueVectors");List<Object> values=new ArrayList<>();for(var e:vectors.entrySet()){List<Object> vector=new ArrayList<>();for(int i=0;i<Array.getLength(e.getValue());i++)vector.add(inter(Array.get(e.getValue(),i)));values.add(m("time_value",e.getKey().toString(),"candidates_by_staff",vector));}result.put("values_in_original_hashmap_iteration_order",values);}
  result.put("after",snapshot(sig,builders));result.put("relation_events",events);return result;
 }
 static Map<String,Object> item(String label,int staff,String kind,String shape,double grade,int x){int y=kind.equals("WHOLE")?120:kind.equals("DEN")?160:128;return m("label",label,"staff_index",staff,"kind",kind,"shape",shape,"grade",grade,"bounds",new int[]{x,y+130*staff,20,kind.equals("WHOLE")?64:16});}
 static List<Map<String,Object>> pair(int staff,int num,int den,double ng,double dg,int dx){String[] digits={"TIME_ZERO","TIME_ONE","TIME_TWO","TIME_THREE","TIME_FOUR","TIME_FIVE","TIME_SIX","TIME_SEVEN","TIME_EIGHT","TIME_NINE"};return new ArrayList<>(List.of(item("n"+staff,staff,"NUM",digits[num],ng,170),item("d"+staff,staff,"DEN",digits[den],dg,170+dx)));}
 Map<String,Object> observe(String name,int count,List<Map<String,Object>> input)throws Exception{return m("name",name,"staff_count",count,"inputs",new ArrayList<>(input),"vector_pass",runPass(input,count,false),"selection_pass",runPass(input,count,true));}
 public void process(){try{
  Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");call(cls("org.audiveris.omr.sheet.grid.GridStep").getConstructor().newInstance(),"doit",sheet);system=((List<?>)call(sheet,"getSystems")).get(0);originalStaves=new ArrayList<>((List<?>)call(system,"getStaves"));if(originalStaves.size()<2)throw new IllegalArgumentException("Control requires original two-staff raster");List<Object> cases=new ArrayList<>();
  cases.add(observe("empty",1,List.of()));for(int dx:new int[]{-17,-16,-15,0,15,16,17})cases.add(observe("dx-"+dx,1,pair(0,3,4,.5,.6,dx)));
  for(int[] nd:new int[][]{{3,3},{4,3},{1,4},{7,8},{5,4},{9,8}})cases.add(observe("rational-"+nd[0]+"-"+nd[1],1,pair(0,nd[0],nd[1],.5,.6,0)));
  cases.add(observe("orphan-num",1,List.of(item("n0",0,"NUM","TIME_THREE",.5,170))));cases.add(observe("orphan-den",1,List.of(item("d0",0,"DEN","TIME_FOUR",.5,170))));
  for(double g:new double[]{.1,.5,.9})cases.add(observe("support-"+g,1,pair(0,3,4,g,g,0)));
  for(boolean reverse:new boolean[]{false,true}){List<Map<String,Object>> x=new ArrayList<>(List.of(item("whole34",0,"WHOLE","TIME_THREE_FOUR",.5,170),item("whole44",0,"WHOLE","TIME_FOUR_FOUR",.5,170)));if(reverse)Collections.reverse(x);cases.add(observe("whole-rational-tie-reverse-"+reverse,1,x));}
  for(double delta:new double[]{0,Math.ulp(.5)}){List<Map<String,Object>> x=new ArrayList<>(List.of(item("first",0,"WHOLE","TIME_THREE_FOUR",.5,170),item("second",0,"WHOLE","TIME_THREE_FOUR",.5+delta,171)));cases.add(observe("same-value-tie-delta-"+delta,1,x));}
  Object rel=cls("org.audiveris.omr.sig.relation.TimeTopBottomRelation").getConstructor().newInstance();double support=(Double)call(rel,"getSourceRatio")-1;double pairGrade=(Double)cls("org.audiveris.omr.sig.GradeUtil").getMethod("contextual",double.class,double.class).invoke(null,.5,.5*support);
  for(double grade:new double[]{Math.nextDown(pairGrade),pairGrade,Math.nextUp(pairGrade)}){List<Map<String,Object>> x=pair(0,3,4,.5,.5,0);x.add(item("whole",0,"WHOLE","TIME_THREE_FOUR",grade,170));cases.add(observe("whole-versus-pair-grade-"+grade,1,x));}
  List<Map<String,Object>> ambiguous=new ArrayList<>(pair(0,3,4,.4,.6,0));ambiguous.add(item("n-alt",0,"NUM","TIME_FOUR",.6,171));ambiguous.add(item("d-alt",0,"DEN","TIME_EIGHT",.5,172));cases.add(observe("ambiguous-four-links",1,ambiguous));Collections.reverse(ambiguous);cases.add(observe("ambiguous-four-links-reverse",1,ambiguous));
  for(double g:new double[]{.49,.5,.51}){List<Map<String,Object>> x=pair(0,3,4,.5,.6,0);x.add(item("neighbor",0,"NEIGHBOR","SHARP",g,170));cases.add(observe("neighbor-grade-"+g,1,x));}
  for(String mode:new String[]{"same","different","missing","common-pair","whole-ties","one-value-missing"}){List<Map<String,Object>> x=new ArrayList<>();if(mode.equals("common-pair")){x.add(item("c",0,"WHOLE","COMMON_TIME",.7,170));x.addAll(pair(1,4,4,.5,.6,0));}else if(mode.equals("whole-ties")||mode.equals("one-value-missing")){for(int st=0;st<2;st++){x.add(item("w34-"+st,st,"WHOLE","TIME_THREE_FOUR",.5,170));if(st==0||!mode.equals("one-value-missing"))x.add(item("w44-"+st,st,"WHOLE","TIME_FOUR_FOUR",.5,170));}}else{x.addAll(pair(0,3,4,.5,.6,0));if(!mode.equals("missing"))x.addAll(pair(1,mode.equals("different")?4:3,4,.5,.6,0));}cases.add(observe("two-staff-"+mode,2,x));}
  set(system,"staves",originalStaves);Files.writeString(Path.of(System.getProperty("native.probe.output")),json(m("controlled_input",true,"geometry_source","original GRID of supplied two-staff raster","injected_state","Each pass uses fresh original SIG with original SigListener, HeaderTimeColumn, HeaderTimeBuilder, cleared staff barline list, explicit header start102/stop158 and declared original inter constructors with null glyph and explicit bounds/grades. Does not call raster candidate finding. Both passes call filterCandidates on all declared staff builders; vector pass calls getValueVectors, selection pass calls checkConsistency. These are direct-method controls, not retrieveTime.","max_halves_dx",observedMaxHalvesDx,"cases",cases))+"\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
